def evaluate(text):
    """Value of an integer arithmetic expression. See TASK.md."""
    if not text or not text.strip():
        raise ValueError("empty expression")

    tokens = tokenize(text)
    parser = Parser(tokens)
    result = parser.parse_expression()

    if not parser.at_end():
        raise ValueError("unexpected token at end")

    return result


def tokenize(text):
    tokens = []
    i = 0
    while i < len(text):
        if text[i] in ' \t':
            i += 1
            continue

        if text[i].isdigit():
            j = i
            while j < len(text) and text[j].isdigit():
                j += 1
            num_str = text[i:j]
            if len(num_str) > 1 and num_str[0] == '0':
                raise ValueError("leading zero")
            tokens.append(('NUM', int(num_str)))
            i = j
        elif text[i:i+2] == '**':
            tokens.append(('**', None))
            i += 2
        elif text[i:i+2] == '//':
            tokens.append(('//', None))
            i += 2
        elif text[i] in '+-*%()':
            tokens.append((text[i], None))
            i += 1
        elif text[i] == '/':
            raise ValueError("/ operator not allowed")
        else:
            raise ValueError(f"invalid character")

    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def at_end(self):
        return self.pos >= len(self.tokens)

    def current_token(self):
        if self.at_end():
            return None
        return self.tokens[self.pos]

    def consume(self):
        token = self.current_token()
        self.pos += 1
        return token

    def peek_type(self):
        token = self.current_token()
        if token:
            return token[0]
        return None

    def parse_expression(self):
        left = self.parse_term()

        while self.peek_type() in ['+', '-']:
            op = self.consume()[0]
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self):
        left = self.parse_unary()

        while self.peek_type() in ['*', '//', '%']:
            op = self.consume()[0]
            right = self.parse_unary()
            if op == '*':
                left = left * right
            elif op == '//':
                if right == 0:
                    raise ZeroDivisionError()
                left = left // right
            else:  # %
                if right == 0:
                    raise ZeroDivisionError()
                left = left % right

        return left

    def parse_unary(self):
        sign = 1
        while self.peek_type() in ['+', '-']:
            op = self.consume()[0]
            if op == '-':
                sign *= -1

        result = self.parse_power()
        return sign * result

    def parse_power(self):
        left = self.parse_primary()

        if self.peek_type() == '**':
            self.consume()
            right = self.parse_unary()
            if right < 0:
                raise ValueError("negative exponent")
            left = left ** right

        return left

    def parse_primary(self):
        token = self.current_token()

        if token is None:
            raise ValueError("unexpected end")

        if token[0] == 'NUM':
            self.consume()
            return token[1]

        if token[0] == '(':
            self.consume()
            if self.peek_type() == ')':
                raise ValueError("empty parentheses")
            result = self.parse_expression()
            if self.peek_type() != ')':
                raise ValueError("missing )")
            self.consume()
            return result

        raise ValueError("expected operand")
